import { motion } from 'framer-motion';

const Projects = () => {
  const projects = [
    {
      title: "AI Static Code Analysis Tool",
      tech: ["Python", "FastAPI", "NLP", "AST Parsing"],
      desc: "Built to detect security vulnerabilities like SQL injection via source code analysis[cite: 9, 11, 15]."
    },
    {
      title: "Social Matching & Recommendation",
      tech: ["SVM", "Flask", "React", "MongoDB"],
      desc: "Implemented SVM-based audio classification to distinguish speech and music[cite: 16, 18, 21]."
    }
  ];

  return (
    <section id="projects" className="py-24 px-10 bg-gray-50">
      <div className="container mx-auto">
        <h3 className="text-4xl font-black mb-16 tracking-tight uppercase">Featured Projects [cite: 8]</h3>
        <div className="grid md:grid-cols-2 gap-8">
          {projects.map((p, i) => (
            <motion.div 
              whileHover={{ y: -10 }}
              key={i} 
              className="bg-white p-10 rounded-3xl shadow-sm border border-gray-100 flex flex-col justify-between h-[350px]"
            >
              <div>
                <div className="flex gap-2 mb-4">
                  {p.tech.map(t => <span key={t} className="text-[10px] font-bold uppercase tracking-widest text-brand-blue">{t}</span>)}
                </div>
                <h4 className="text-3xl font-bold mb-4">{p.title}</h4>
                <p className="text-gray-500 leading-relaxed">{p.desc}</p>
              </div>
              <button className="mt-6 font-bold self-start border-b-2 border-black pb-1">View Project</button>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Projects;
